"""Validate portable wheel-distance calibration evidence without hardware imports.

A profile supplies one positive, dimensionless multiplier relative to explicitly
recorded wheel geometry. Loading it does not change any setting. A profile from a
different chassis is rejected even if its fitted error happens to be small.
"""
import datetime
import hashlib
import json
import math
from pathlib import Path
import re

import config


SCHEMA = 'rover-wheel-distance-calibration-v1'
SOURCE_ROLES = frozenset(('checkpoint_csv', 'raw_recording', 'replay_results', 'estimator_source'))
DATA_ROLES = frozenset(('calibration_training', 'previously_tuned_historical'))


class FrozenDict(dict):
    """Recursively frozen profile objects that remain JSON serializable."""
    def _immutable(self, *args, **kwargs):
        raise TypeError('Calibration provenance is immutable')

    __setitem__ = __delitem__ = clear = pop = popitem = setdefault = update = __ior__ = _immutable

    def __copy__(self):
        return self

    def __deepcopy__(self, memo):
        return self


def _freeze(value):
    if isinstance(value, dict):
        return FrozenDict((key, _freeze(item)) for key, item in value.items())
    if isinstance(value, list):
        return tuple(_freeze(item) for item in value)
    return value


def _fields(value, expected, label):
    if not isinstance(value, dict) or set(value) != set(expected):
        raise ValueError(f'{label} must contain exactly: {", ".join(sorted(expected))}')


def _number(value, label, *, positive=False):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(f'{label} must be a finite number')
    try:
        number = float(value)
    except (ValueError, OverflowError):
        raise ValueError(f'{label} must be a finite number') from None
    if not math.isfinite(number) or (positive and number <= 0):
        raise ValueError(f'{label} must be finite' + (' and positive' if positive else ''))
    return number


def _text(value, label, limit=4096):
    if not isinstance(value, str) or not value.strip() or len(value) > limit or '\x00' in value:
        raise ValueError(f'{label} must be nonempty text of at most {limit} characters')
    return value


def validate_geometry(geometry):
    """Return normalized declared geometry; no inference from source names."""
    _fields(geometry, ('wheel_radius_m', 'wheelbase_m', 'wheel_sign'), 'geometry')
    signs = geometry['wheel_sign']
    if not isinstance(signs, (list, tuple)) or len(signs) != 4 or any(
            isinstance(value, bool) or not isinstance(value, int) or value not in (-1, 1)
            for value in signs):
        raise ValueError('geometry.wheel_sign must contain four integer signs, each -1 or +1')
    return {
        'wheel_radius_m': _number(geometry['wheel_radius_m'], 'geometry.wheel_radius_m', positive=True),
        'wheelbase_m': _number(geometry['wheelbase_m'], 'geometry.wheelbase_m', positive=True),
        'wheel_sign': list(signs),
    }


def fit_distance_scale(estimated_x, measured_x):
    """Fit one positive scale through zero; no offset, windows, or per-stop fit."""
    estimates, measurements = list(estimated_x), list(measured_x)
    if len(estimates) != len(measurements) or len(estimates) < 2:
        raise ValueError('At least two matching fixed checkpoints are required')
    x = [_number(value, 'estimated_x') for value in estimates]
    y = [_number(value, 'measured_x') for value in measurements]
    try:
        denominator = math.fsum(value * value for value in x)
        numerator = math.fsum(a * b for a, b in zip(x, y))
        scale = numerator / denominator if denominator > 0 else float('nan')
    except (OverflowError, ValueError):
        scale = float('nan')
    return _number(scale, 'fitted wheel_distance_scale', positive=True)


def validate_profile(profile, *, geometry):
    """Validate the complete v1 schema and exact declared chassis compatibility."""
    _fields(profile, ('schema', 'quantity', 'units', 'wheel_distance_scale', 'geometry',
                      'provenance', 'fit'), 'profile')
    if profile['schema'] != SCHEMA or profile['quantity'] != 'wheel_distance_scale':
        raise ValueError('Unsupported wheel calibration schema or quantity')
    if profile['units'] != 'dimensionless':
        raise ValueError('Wheel distance scale units must be dimensionless; geometry uses meters')
    scale = _number(profile['wheel_distance_scale'], 'wheel_distance_scale', positive=True)
    declared, requested = validate_geometry(profile['geometry']), validate_geometry(geometry)
    if declared != requested:
        raise ValueError(f'Wheel calibration geometry mismatch: profile={declared}, runtime={requested}')
    provenance = profile['provenance']
    _fields(provenance, ('created_utc', 'geometry_identity', 'data_role', 'training_runs',
                         'sources', 'limitations', 'unseen_validation', 'absolute_accuracy_validated'), 'provenance')
    timestamp = _text(provenance['created_utc'], 'provenance.created_utc', 80)
    try:
        created = datetime.datetime.fromisoformat(timestamp.replace('Z', '+00:00'))
    except ValueError:
        raise ValueError('provenance.created_utc must be an ISO8601 UTC timestamp') from None
    if created.tzinfo is None or created.utcoffset() != datetime.timedelta(0):
        raise ValueError('provenance.created_utc must identify UTC explicitly')
    _text(provenance['geometry_identity'], 'provenance.geometry_identity', 256)
    if not isinstance(provenance['data_role'], str) or provenance['data_role'] not in DATA_ROLES:
        raise ValueError('provenance.data_role must describe calibration training or historical tuning')
    runs = provenance['training_runs']
    if not isinstance(runs, list) or not 1 <= len(runs) <= 32:
        raise ValueError('provenance.training_runs must identify 1 to 32 runs')
    for run in runs:
        _text(run, 'training run', 256)
    if len(set(runs)) != len(runs):
        raise ValueError('Training run identifiers must be unique')
    sources = provenance['sources']
    if not isinstance(sources, list) or not 3 <= len(sources) <= 64:
        raise ValueError('provenance.sources must retain checkpoint, raw, and replay-result identities')
    roles, paths = set(), set()
    for source in sources:
        _fields(source, ('path', 'sha256', 'role'), 'provenance source')
        path = _text(source['path'], 'source.path')
        if path in paths:
            raise ValueError('Each provenance source path must appear once')
        paths.add(path)
        if not isinstance(source['sha256'], str) or re.fullmatch(r'[0-9a-f]{64}', source['sha256']) is None:
            raise ValueError('Each provenance source needs a lowercase SHA256')
        if not isinstance(source['role'], str) or source['role'] not in SOURCE_ROLES:
            raise ValueError('Unsupported provenance source role')
        roles.add(source['role'])
    if not {'checkpoint_csv', 'raw_recording', 'replay_results'} <= roles:
        raise ValueError('Checkpoint CSV, original recording, and replay-result sources are required')
    limitations = provenance['limitations']
    if not isinstance(limitations, list) or not 1 <= len(limitations) <= 32:
        raise ValueError('Profile must retain its calibration limitations')
    for item in limitations:
        _text(item, 'provenance limitation')
    if provenance['unseen_validation'] is not False or provenance['absolute_accuracy_validated'] is not False:
        raise ValueError('Calibration profile cannot claim unseen validation or validated absolute accuracy')
    fit = profile['fit']
    _fields(fit, ('method', 'measured_checkpoint_count', 'initial_reference_count', 'fixed_timestamps',
                  'checkpoint_columns', 'training_rmse_x_m', 'training_max_abs_x_error_m'), 'fit')
    if fit['method'] != 'zero_intercept_least_squares' or fit['fixed_timestamps'] is not True:
        raise ValueError('Profile requires fixed checkpoints and one zero-intercept least-squares scale')
    count = fit['measured_checkpoint_count']
    if isinstance(count, bool) or not isinstance(count, int) or count < 2:
        raise ValueError('At least two measured checkpoints are required')
    if type(fit['initial_reference_count']) is not int or fit['initial_reference_count'] not in (0, 1):
        raise ValueError('initial_reference_count must be 0 or 1; origin is not independent truth')
    columns = fit['checkpoint_columns']
    _fields(columns, ('estimated_x', 'measured_x', 'run', 'time', 'sample_time'), 'checkpoint columns')
    for value in columns.values():
        _text(value, 'checkpoint column', 256)
    for key in ('training_rmse_x_m', 'training_max_abs_x_error_m'):
        if _number(fit[key], key) < 0:
            raise ValueError(f'{key} must be nonnegative')
    if fit['training_max_abs_x_error_m'] < fit['training_rmse_x_m']:
        raise ValueError('Maximum training error cannot be smaller than RMS error')
    return scale


def _unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError(f'Duplicate JSON key: {key}')
        result[key] = value
    return result


def load_profile(path, *, geometry):
    """Load an explicit compatible profile; return scale and immutable evidence.

    Source SHA256/path fields preserve the recorded calibration identity. Source
    recordings need not be installed on the Rover: this loader verifies schema
    and chassis compatibility, while the fitter verifies bytes when creating the
    profile. It also hashes the exact profile JSON bytes used for this run.
    """
    source = Path(path).expanduser().resolve()
    maximum_bytes = config.WHEEL_CALIBRATION_PROFILE_MAX_BYTES
    if type(maximum_bytes) is not int or maximum_bytes <= 0:
        raise ValueError('WHEEL_CALIBRATION_PROFILE_MAX_BYTES must be a positive integer')
    try:
        with source.open('rb') as stream:
            raw = stream.read(maximum_bytes + 1)
    except OSError as error:
        raise ValueError(f'Cannot read wheel calibration profile: {source}: {error}') from error
    if len(raw) > maximum_bytes:
        raise ValueError(f'Wheel calibration profile exceeds {maximum_bytes} bytes')
    try:
        profile = json.loads(raw.decode('utf-8'), object_pairs_hook=_unique_object,
                             parse_constant=lambda value: (_ for _ in ()).throw(ValueError(f'Nonfinite JSON constant: {value}')))
    except (UnicodeError, json.JSONDecodeError, RecursionError) as error:
        raise ValueError(f'Invalid wheel calibration JSON: {error}') from error
    scale = validate_profile(profile, geometry=geometry)
    return {'wheel_distance_scale': scale, 'provenance': _freeze({
        'profile_path': str(source), 'profile_sha256': hashlib.sha256(raw).hexdigest(),
        'profile_schema': SCHEMA, 'profile': profile,
    })}

imu_process.py.text:
"""One spawned BMI088 owner, with ordered request/response acquisition.

Only the child opens SPI. Parent-side scheduling cannot lengthen a child's
SPI-call brackets. It can still delay the next request or delivery, so the
existing FIFO, acquisition-gap and freshness checks remain necessary.
"""
from copy import deepcopy
from datetime import datetime, timezone
import hashlib
import multiprocessing
from pathlib import Path
import pickle
import queue
import threading
import time

import config
import imu_reader


class IMUProcessCleanupError(imu_reader.IMUError):
    """A previous owner is not confirmed stopped; do not spawn another."""


_owners = set()
_owners_lock = threading.RLock()
_source = Path(__file__).read_bytes()
_source_identity = dict(sha256=hashlib.sha256(_source).hexdigest(), text=_source.decode('utf-8'))
_source_captured_utc = datetime.now(timezone.utc).isoformat()


def _send(connection, reply):
    payload = pickle.dumps(reply, protocol=pickle.HIGHEST_PROTOCOL)
    if len(payload) > config.IMU_PROCESS_MAX_REPLY_BYTES:
        raise imu_reader.IMUError('IMU process reply exceeds bounded payload size')
    connection.send_bytes(payload)


def _factory():
    return imu_reader.create_imu('bmi088')


def _stats(reader):
    try:
        return reader.stats() if hasattr(reader, 'stats') else {}
    except Exception as exc:
        return {'stats_error': f'{type(exc).__name__}: {exc}'}


def _worker(connection, stop, factory):
    reader = None
    sequence = 0
    try:
        reader = factory()
        metadata = deepcopy(reader.metadata()) if hasattr(reader, 'metadata') else {'sensor': 'BMI088'}
        metadata.setdefault('sources', {})['imu_process.py'] = deepcopy(_source_identity)
        metadata['acquisition_process_source_captured_utc'] = _source_captured_utc
        _send(connection, dict(protocol=1, sequence=0, kind='ready',
                               metadata=metadata, stats=_stats(reader)))
        while not stop.is_set():
            if not connection.poll(.05):
                continue
            request = connection.recv()
            if (not isinstance(request, dict) or request.get('kind') != 'read'
                    or type(request.get('sequence')) is not int
                    or request['sequence'] != sequence + 1):
                raise imu_reader.IMUError('Invalid IMU process request sequence')
            sequence = request['sequence']
            try:
                sample = reader.read()
            except imu_reader.IMUSampleError as exc:
                # Preserve exact reason and the same read's fresh diagnostic.
                _send(connection, dict(protocol=1, sequence=sequence, kind='sample_error',
                                       error=str(exc), stats=_stats(reader)))
            else:
                _send(connection, dict(protocol=1, sequence=sequence, kind='sample',
                                       sample=sample, stats=_stats(reader)))
    except (EOFError, BrokenPipeError):
        pass
    except BaseException as exc:
        try:
            _send(connection, dict(protocol=1, sequence=sequence, kind='fatal_error',
                                   error=f'{type(exc).__name__}: {exc}',
                                   stats=_stats(reader) if reader is not None else {}))
        except (OSError, EOFError, imu_reader.IMUError):
            pass
    finally:
        if reader is not None:
            try:
                reader.close()
            except Exception:
                pass
        connection.close()


class BMI088ProcessReader:
    def __init__(self, *, factory=None, stop_event=None, start_timeout=None,
                 read_timeout=None, close_timeout=None):
        self._external_stop = stop_event
        self._start_timeout = config.IMU_PROCESS_START_TIMEOUT_S if start_timeout is None else start_timeout
        self._read_timeout = config.IMU_PROCESS_READ_TIMEOUT_S if read_timeout is None else read_timeout
        self._close_timeout = config.IMU_PROCESS_CLOSE_TIMEOUT_S if close_timeout is None else close_timeout
        if min(self._start_timeout, self._read_timeout, self._close_timeout) <= 0:
            raise ValueError('IMU process deadlines must be positive')
        self._closed = False
        self._cleanup_complete = False
        self._sequence = 0
        self._stats = {}
        self._metadata = None
        self._responses = queue.Queue(maxsize=2)
        self._receive_error = None
        self._close_lock = threading.RLock()
        context = multiprocessing.get_context('spawn')
        self._stop = context.Event()
        self._connection, child_connection = context.Pipe(duplex=True)
        self._process = context.Process(target=_worker,
                                        args=(child_connection, self._stop, factory or _factory),
                                        name='bmi088-spi', daemon=True)
        self._receiver = None
        try:
            with _owners_lock:
                previous_owners = list(_owners)
            for previous in previous_owners:
                if not previous._closed:
                    raise IMUProcessCleanupError('Another BMI088 process owner is still active')
                previous.close()  # Raises while an old owner remains unreaped.
            with _owners_lock:
                if _owners:
                    raise IMUProcessCleanupError('Another BMI088 process owner is still active')
                _owners.add(self)
        except BaseException:
            child_connection.close()
            self._connection.close()
            raise
        try:
            self._process.start()
            # Close this unused endpoint, so child exit always exposes EOF.
            child_connection.close()
            # Connection.recv can wait for a partial frame after poll(). Keep
            # that blocking operation outside the deadline-enforcing caller.
            self._receiver = threading.Thread(target=self._receive_loop,
                                              name='imu-process-ipc', daemon=True)
            self._receiver.start()
            reply = self._receive(0, self._start_timeout)
            if reply['kind'] != 'ready' or not isinstance(reply.get('metadata'), dict):
                self._fatal(reply.get('error') or 'Invalid IMU process startup reply')
            self._metadata = deepcopy(reply['metadata'])
            self._metadata['acquisition_process'] = dict(
                pid=self._process.pid, start_method='spawn', transport='one read request and ordered response',
                parent_proxy_sha256=_source_identity['sha256'],
                parent_source_captured_utc=_source_captured_utc,
                timestamps='original child acquisition monotonic timestamps; no delivery restamping',
                buffering='one outstanding request; no autonomous sample queue or silent dropping')
            if self._metadata['sources']['imu_process.py']['sha256'] != _source_identity['sha256']:
                self._metadata['acquisition_process']['parent_proxy_source'] = deepcopy(_source_identity)
        except BaseException:
            child_connection.close()
            self.close()
            raise

    def _receive_loop(self):
        try:
            while True:
                payload = pickle.loads(self._connection.recv_bytes(config.IMU_PROCESS_MAX_REPLY_BYTES))
                try:
                    self._responses.put_nowait(payload)
                except queue.Full:
                    raise imu_reader.IMUError('Unexpected extra IMU process response')
        except BaseException as exc:
            self._receive_error = f'{type(exc).__name__}: {exc}'

    def _receive(self, sequence, timeout):
        deadline = time.monotonic() + timeout
        while True:
            if self._closed or (self._external_stop is not None and self._external_stop.is_set()):
                self._fatal('IMU process acquisition cancelled')
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                self._fatal('IMU process response timeout')
            try:
                reply = self._responses.get(timeout=min(.02, remaining))
            except queue.Empty:
                if self._receive_error:
                    self._fatal('IMU process IPC ended: ' + self._receive_error)
                continue
            if (not isinstance(reply, dict) or reply.get('protocol') != 1
                    or type(reply.get('sequence')) is not int or reply['sequence'] != sequence
                    or reply.get('kind') not in ('ready', 'sample', 'sample_error', 'fatal_error')
                    or not isinstance(reply.get('stats'), dict)):
                self._fatal('Invalid IMU process response/sequence')
            self._stats = deepcopy(reply['stats'])
            return reply

    def _fatal(self, reason):
        self.close()
        raise imu_reader.IMUError(reason)

    def read(self):
        if self._closed:
            raise imu_reader.IMUError('BMI088 acquisition process is closed')
        self._sequence += 1
        try:
            self._connection.send(dict(kind='read', sequence=self._sequence))
        except (OSError, EOFError) as exc:
            self._fatal(f'IMU process request failed: {exc}')
        reply = self._receive(self._sequence, self._read_timeout)
        if reply['kind'] == 'sample':
            if reply.get('sample') is not None and not isinstance(reply['sample'], dict):
                self._fatal('Invalid IMU process sample payload')
            return reply['sample']
        if reply['kind'] == 'sample_error' and isinstance(reply.get('error'), str):
            raise imu_reader.IMUSampleError(reply['error'])
        self._fatal(reply.get('error') or 'Unexpected IMU process read reply')

    def metadata(self):
        return deepcopy(self._metadata)

    def stats(self):
        return deepcopy(self._stats)

    def close(self):
        with self._close_lock:
            if self._cleanup_complete:
                return
            self._closed = True
            self._stop.set()
            if self._process.pid is not None:
                self._process.join(self._close_timeout)
                if self._process.is_alive():
                    self._process.terminate()
                    self._process.join(self._close_timeout)
                if self._process.is_alive():
                    self._process.kill()
                    self._process.join(self._close_timeout)
                if self._process.is_alive():
                    raise IMUProcessCleanupError(
                        f'Previous BMI088 owner PID {self._process.pid} has not stopped; retry blocked')
            self._connection.close()
            if self._receiver is not None and self._receiver is not threading.current_thread():
                self._receiver.join(self._close_timeout)
                if self._receiver.is_alive():
                    raise IMUProcessCleanupError('Previous BMI088 IPC receiver has not stopped; retry blocked')
            self._cleanup_complete = True
            with _owners_lock:
                _owners.discard(self)
